'use strict';
import { initConcierge } from './concierge.js';
import { initInstall } from './install.js';
import { initReels } from './social.js';
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
// Reveal enhancements never hide content when scripting or observer support fails.
if('IntersectionObserver' in window){document.documentElement.classList.add('js');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
const closeMenu=()=>{nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Open navigation')};
menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();menu.focus()}});
document.addEventListener('click',e=>{if(nav?.classList.contains('open')&&!nav.contains(e.target)&&!menu.contains(e.target))closeMenu()});
matchMedia('(min-width: 981px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
// Filters act on real service cards, with state exposed to assistive technology.
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.service-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;card.classList.add('visible')})}));
const photo=document.querySelector('#gallery-photo');
if(photo){let index=0,timer,paused=reduced.matches,intersecting=false;const images=['assets/treatment-1.webp','assets/treatment-2.webp','assets/treatment-3.webp'];const pause=document.querySelector('#gallery-pause');const render=()=>{photo.src=images[index];photo.alt=`Madero Slim supplied body treatment photo ${index+1}`;document.querySelector('#gallery-count').textContent=`0${index+1} / 03`};const next=delta=>{index=(index+delta+images.length)%images.length;render()};const sync=()=>{clearInterval(timer);pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');pause.setAttribute('aria-pressed',String(paused));if(!paused&&!document.hidden&&intersecting)timer=setInterval(()=>next(1),6000)};document.querySelector('#gallery-prev').onclick=()=>{next(-1);sync()};document.querySelector('#gallery-next').onclick=()=>{next(1);sync()};pause.onclick=()=>{paused=!paused;sync()};document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',e=>{paused=e.matches;sync()});if('IntersectionObserver'in window)new IntersectionObserver(e=>{intersecting=e[0].isIntersecting;sync()}).observe(photo);else{intersecting=true}sync()}
// Desktop: pointer-driven perspective with a CSS wooden tool. No canvas rendering loop.
const desktop=document.querySelector('.desktop-experience'),desktopQuery=matchMedia('(min-width: 761px) and (hover: hover)');
if(desktop){const plane=desktop.querySelector('.hero-photo-plane'),pause=desktop.querySelector('.motion-toggle');let paused=reduced.matches;const sync=()=>{desktop.classList.toggle('motion-paused',paused);pause.textContent=paused?'Play motion ▷':'Pause motion Ⅱ';pause.setAttribute('aria-pressed',String(paused));plane.style.transform=''};desktop.addEventListener('pointermove',e=>{if(paused||!desktopQuery.matches||reduced.matches)return;const r=desktop.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;plane.style.transform=`rotateY(${x*7}deg) rotateX(${-y*5}deg)`});desktop.addEventListener('pointerleave',()=>plane.style.transform='');pause.onclick=()=>{paused=!paused;sync()};reduced.addEventListener('change',e=>{paused=e.matches;sync()});sync()}
// Mobile has its own photo sequence, swipe behaviour and gentle breathing detail.
const mobile=document.querySelector('.mobile-experience');
if(mobile){const query=matchMedia('(max-width: 760px)'),image=mobile.querySelector('img'),pause=mobile.querySelector('#mobile-motion-toggle');const slides=[['massage','BODY & BALANCE','A full-body exhale.','Illustrative body massage from Unsplash'],['facial','FACE & GLOW','A little lift. A fresh start.','Illustrative facial massage from Unsplash'],['ritual','REST & RESTORE','Slow looks good on you.','Illustrative spa ritual from Unsplash']];let index=0,paused=reduced.matches,timer,intersecting=false,startX=0;const show=i=>{index=(i+slides.length)%slides.length;const [src,type,name,alt]=slides[index];image.src=`assets/${src}.webp`;image.alt=alt;document.querySelector('#mobile-ritual-type').textContent=type;document.querySelector('#mobile-ritual-name').textContent=name;mobile.querySelectorAll('[data-slide]').forEach(b=>{const active=Number(b.dataset.slide)===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})};const sync=()=>{clearInterval(timer);mobile.classList.toggle('is-paused',paused||!query.matches||document.hidden||!intersecting);pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-label',paused?'Play mobile animation':'Pause mobile animation');pause.setAttribute('aria-pressed',String(paused));if(query.matches&&!paused&&!document.hidden&&intersecting)timer=setInterval(()=>show(index+1),7000)};mobile.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{show(Number(b.dataset.slide));sync()});mobile.querySelector('.mobile-visual').addEventListener('touchstart',e=>{startX=e.changedTouches[0].screenX},{passive:true});mobile.querySelector('.mobile-visual').addEventListener('touchend',e=>{const delta=e.changedTouches[0].screenX-startX;if(Math.abs(delta)>50){show(index+(delta<0?1:-1));sync()}},{passive:true});pause.onclick=()=>{paused=!paused;sync()};query.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',e=>{paused=e.matches;sync()});if('IntersectionObserver'in window)new IntersectionObserver(e=>{intersecting=e[0].isIntersecting;sync()}).observe(mobile);else{intersecting=true}sync()}
const ask=document.querySelector('#ask-booking'),treatment=document.querySelector('#treatment');
if(treatment){const requested=new URLSearchParams(location.search).get('treatment');const links={"face-lifting":0,"deep-detox":1,"lymphatic-drainage":2,"madero-therapy":3,"deep-tissue":4,"cupping":5,"head-shoulder-feet":6,"hot-stone":7};if(requested in links)treatment.selectedIndex=links[requested]}
ask?.addEventListener('click',()=>{const text=`Hello Madero Slim! I’m interested in ${treatment.value} for a home session in ${document.querySelector('#area').value}. Please confirm availability and the final price.`;window.open('https://wa.me/971521275611?text='+encodeURIComponent(text),'_blank','noopener')});
// App navigation is built once and is separate from the desktop navigation.
